import { MeshBasicNodeMaterial, MeshStandardNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, mix, smoothstep, mul, sub, length } from 'three/tsl';
import { gsap } from 'gsap';

function makeWatchMaterial(src, THREE) {
  const color = src.color ? src.color.clone() : new THREE.Color('#e8ecf2');
  const mat = new MeshPhysicalNodeMaterial({
    color,
    map: src.map ?? null,
    normalMap: src.normalMap ?? null,
    roughnessMap: src.roughnessMap ?? null,
    metalnessMap: src.metalnessMap ?? null,
    roughness: 0.52,
    metalness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.4,
    anisotropy: 0.8,
  });
  if (src.emissive) {
    mat.emissive = src.emissive.clone();
    mat.emissiveIntensity = Math.min(1.6, src.emissiveIntensity ?? 1.0);
  }
  return mat;
}

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();
  const root = new THREE.Group();
  group.add(root);

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const surface = new THREE.Color(colors.surface ?? '#14141a');
  const stops = colors.gradientStops ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 0.55, hex: '#101017' },
    { at: 1, hex: '#16161d' },
  ];
  const c0 = new THREE.Color(stops[0].hex);
  const c1 = new THREE.Color(stops[1].hex);
  const c2 = new THREE.Color(stops[2].hex);

  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const gradNode = mix(
    mix(vec3(c0.r, c0.g, c0.b), vec3(c1.r, c1.g, c1.b), smoothstep(0.0, 0.55, uv().y)),
    vec3(c2.r, c2.g, c2.b),
    smoothstep(0.55, 1.0, uv().y)
  );
  const backdropMat = new MeshBasicNodeMaterial({ side: THREE.FrontSide });
  backdropMat.colorNode = gradNode;
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  const plinthGeo = new THREE.CylinderGeometry(1.4, 1.4, 0.25, 64);
  const plinthMat = new MeshStandardNodeMaterial({
    color: surface,
    roughness: 0.7,
    metalness: 0.3,
  });
  const plinth = new THREE.Mesh(plinthGeo, plinthMat);
  plinth.position.y = -1.1 - 0.125;
  plinth.castShadow = true;
  plinth.receiveShadow = true;
  root.add(plinth);

  const shadowGeo = new THREE.CircleGeometry(1.6, 64);
  const radialDist = length(sub(uv(), vec2(0.5, 0.5)));
  const radialNode = smoothstep(0.5, 0.0, radialDist);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, side: THREE.DoubleSide });
  shadowMat.colorNode = vec3(0, 0, 0);
  shadowMat.opacityNode = mul(radialNode, 0.55);
  const shadow = new THREE.Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = -1.225 - 0.02;
  root.add(shadow);

  const keyLight = new THREE.SpotLight(new THREE.Color('#ffffff'), 1.1);
  keyLight.position.set(3.5, 4.5, 5);
  keyLight.angle = Math.PI / 5;
  keyLight.penumbra = 0.3;
  keyLight.castShadow = true;
  root.add(keyLight);

  const accentLight = new THREE.SpotLight(new THREE.Color(colors.accent ?? '#ff2a38'), 0.9);
  accentLight.position.set(-4, 1.5, 3.5);
  accentLight.angle = Math.PI / 8;
  accentLight.penumbra = 0.25;
  accentLight.target.position.set(0, -0.2, 0);
  accentLight.castShadow = false;
  root.add(accentLight);
  root.add(accentLight.target);

  const backLight = new THREE.SpotLight(new THREE.Color('#e8ecf2'), 0.7);
  backLight.position.set(-2, 3, -4);
  backLight.angle = Math.PI / 5;
  backLight.penumbra = 0.4;
  backLight.target.position.set(0, 0, 0);
  backLight.castShadow = false;
  root.add(backLight);
  root.add(backLight.target);

  const fillLight = new THREE.PointLight(new THREE.Color('#e8ecf2'), 0.3);
  fillLight.position.set(2, 2.5, -2);
  root.add(fillLight);

  const heroGroup = new THREE.Group();
  root.add(heroGroup);

  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    const watchScene = gltf.scene;
    watchScene.traverse((child) => {
      if (child.isMesh) {
        child.castShadow = true;
        child.receiveShadow = true;
        const mats = Array.isArray(child.material) ? child.material : [child.material];
        child.material = mats.length === 1
          ? makeWatchMaterial(mats[0], THREE)
          : mats.map((m) => makeWatchMaterial(m, THREE));
      }
    });

    const box = new THREE.Box3().setFromObject(watchScene);
    const targetHeight = 2.2;
    const scale = box.max.y > box.min.y ? targetHeight / (box.max.y - box.min.y) : 1;
    watchScene.scale.setScalar(scale);

    const scaledBox = new THREE.Box3().setFromObject(watchScene);
    const center = scaledBox.getCenter(new THREE.Vector3());
    watchScene.position.set(
      -center.x,
      -1.1 - scaledBox.min.y,
      -center.z
    );

    heroGroup.add(watchScene);

    gsap.from(heroGroup.scale, {
      x: 0.96,
      y: 0.96,
      z: 0.96,
      duration: 0.8,
      ease: 'power3.out',
    });
  });

  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    const typography = item.typography || {};
    const opts = {
      color: item.color ?? '#e8ecf2',
      align: 'center',
    };
    if (typography.fontSize) opts.fontSize = typography.fontSize;
    if (typeof typography.letterSpacing === 'number') {
      opts.letterSpacingPx = typography.fontSize * typography.letterSpacing;
    }
    const label = ctx.fontAtlas.createText(String(item.text), opts);
    let y = -1.5;
    if (item.role === 'body') y = -2.0;
    else if (item.role === 'caption') y = -2.45;
    label.position.set(0, y, 0.5);
    root.add(label);
  }

  let orbitResult = null;
  let depthResult = null;
  for (const p of config.cinematicPrimitives ?? []) {
    if (p.name === 'orbit') {
      orbitResult = ctx.primitives['orbit'](heroGroup, p.params ?? { speed: 0.15, radius: 0.6 });
    } else if (p.name === 'depth-rotate') {
      depthResult = ctx.primitives['depth-rotate'](heroGroup, p.params ?? { maxDeg: 6 });
    }
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    if (orbitResult?.cleanup) orbitResult.cleanup();
    if (depthResult?.cleanup) depthResult.cleanup();
    gsap.killTweensOf(heroGroup);
    gsap.killTweensOf(heroGroup.scale);
    gsap.killTweensOf(heroGroup.rotation);
    backdropGeo.dispose();
    backdropMat.dispose();
    plinthGeo.dispose();
    plinthMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    heroGroup.traverse((o) => {
      if (o.isMesh) {
        o.geometry?.dispose();
        if (Array.isArray(o.material)) {
          o.material.forEach((m) => m?.dispose());
        } else {
          o.material?.dispose();
        }
      }
    });
  };

  return group;
}
